from fitkin import *
from scipy.spatial import cKDTree

def toolcloud(o):
 pp=[]
 for c in cams:
  p,col=cloud(o,c);mask=(p[:,:,2]>.545)&(p[:,:,2]<.62)&(p[:,:,1]<.19)&(p[:,:,1]>-.12)&(abs(p[:,:,0])<.26)&(col.max(-1).astype(float)-col.min(-1)<30)&(col.min(-1)<195)
  pp.append(p[mask])
 return np.concatenate(pp)

def ghostcloud(o):
 pp=[]
 for c in cams:
  p,col=cloud(o,c);col=col.astype(float);mask=(col[:,:,1]>1.7*col[:,:,0]+20)&(col[:,:,1]>1.7*col[:,:,2]+20)&(p[:,:,2]>.6)&(p[:,:,2]<.72)
  pp.append(p[mask])
 return np.concatenate(pp)

if __name__=='__main__':
 o=loadobs('initial');a=toolcloud(o);g=ghostcloud(o); print('tool',a.shape,a.min(0),a.max(0));print('ghost',g.shape,g.min(0),g.max(0))
 goal=np.array(o.meta['task']['goal']);G=np.eye(4);G[:3,:3]=Rot.from_quat(goal[3:]).as_matrix();G[:3,3]=goal[:3]
 np.save(ROOT/'tool_initial.npy',a);np.save(ROOT/'ghost_initial.npy',g);np.save(ROOT/'ghost_local.npy',(g-G[:3,3])@G[:3,:3])
 # Initial yaw-rotation alignment, the two hammer faces may also be flipped.
 best=None
 for flip in [0,np.pi]:
  for yaw in [0,np.pi]:
   R=Rot.from_euler('z',yaw).as_matrix()@Rot.from_euler('x',flip).as_matrix()
   T=np.eye(4);T[:3,:3]=R;T[:3,3]=g.mean(0)-R@a.mean(0)
   T,err,n=icp(a,g,init=T,iters=180,cut=.06)
   print('fit',flip,yaw,err,n,T)
   if best is None or err<best[0]:best=(err,T)
 T=best[1];P=np.linalg.inv(T)@G;np.save(ROOT/'tool_pose_initial.npy',P);print('POSE',P)
